"use client";

import * as React from "react";
import styles from "../styles/image-compare.module.css";

export interface ImageCompareProps {
  /** URL of the "before" image (defaults to a muted gradient scene) */
  beforeSrc?: string;
  /** URL of the "after" image (defaults to a vivid gradient scene) */
  afterSrc?: string;
  /** Label and alt text of the before side */
  beforeLabel?: string;
  /** Label and alt text of the after side */
  afterLabel?: string;
  /** Controlled divider position in percent (0–100) */
  value?: number;
  /** Initial divider position in percent when uncontrolled */
  defaultValue?: number;
  /** Called with the new position while dragging or using the keyboard */
  onValueChange?: (value: number) => void;
  /** Divider direction: horizontal splits left/right, vertical splits top/bottom */
  orientation?: "horizontal" | "vertical";
  /** Show the Before/After corner labels */
  showLabels?: boolean;
  /** Play a short hint sweep on mount */
  intro?: boolean;
  /** Divider and handle color */
  handleColor?: string;
  /** Color of the handle arrows and focus glow */
  accentColor?: string;
  /** Keyboard step in percent */
  step?: number;
  /** Height in px */
  height?: number;
  /** Corner radius in px */
  borderRadius?: number;
  /** Optional className merged onto the root */
  className?: string;
  /** Optional inline styles merged onto the root */
  style?: React.CSSProperties;
}

const clamp = (n: number) => Math.min(100, Math.max(0, n));

function Scene({ src, alt, vivid }: { src?: string; alt: string; vivid: boolean }) {
  if (src) return <img className={styles.img} src={src} alt={alt} draggable={false} />;
  return (
    <div className={styles.scene} data-vivid={vivid ? "" : undefined} role="img" aria-label={alt}>
      <span className={styles.sun} />
      <span className={`${styles.ridge} ${styles.ridgeBack}`} />
      <span className={`${styles.ridge} ${styles.ridgeMid}`} />
      <span className={`${styles.ridge} ${styles.ridgeFront}`} />
      <span className={styles.water} />
    </div>
  );
}

export function ImageCompare({
  beforeSrc,
  afterSrc,
  beforeLabel = "Before",
  afterLabel = "After",
  value: valueProp,
  defaultValue = 50,
  onValueChange,
  orientation = "horizontal",
  showLabels = true,
  intro = true,
  handleColor = "#ffffff",
  accentColor = "#6366f1",
  step = 2,
  height = 360,
  borderRadius = 12,
  className = "",
  style,
}: ImageCompareProps) {
  const [inner, setInner] = React.useState(clamp(defaultValue));
  const controlled = valueProp !== undefined;
  const pos = clamp(controlled ? valueProp : inner);
  const [wiggle, setWiggle] = React.useState(0);
  const [dragging, setDragging] = React.useState(false);
  const rootRef = React.useRef<HTMLDivElement>(null);
  const rafRef = React.useRef(0);
  const vertical = orientation === "vertical";

  React.useEffect(() => {
    if (!intro || typeof window === "undefined") return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const start = performance.now();
    const tick = (now: number) => {
      const t = Math.min(1, (now - start) / 1600);
      setWiggle(t >= 1 ? 0 : 16 * Math.sin(t * Math.PI * 3) * (1 - t) * (1 - t));
      if (t < 1) rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(rafRef.current);
  }, [intro]);

  const set = (n: number) => {
    const next = Math.round(clamp(n) * 10) / 10;
    cancelAnimationFrame(rafRef.current);
    setWiggle(0);
    if (!controlled) setInner(next);
    onValueChange?.(next);
  };

  const fromPointer = (e: React.PointerEvent) => {
    const r = rootRef.current?.getBoundingClientRect();
    if (!r) return;
    set(vertical ? ((e.clientY - r.top) / r.height) * 100 : ((e.clientX - r.left) / r.width) * 100);
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    const map: Record<string, number> = {
      ArrowLeft: -step,
      ArrowDown: vertical ? step : -step,
      ArrowRight: step,
      ArrowUp: vertical ? -step : step,
      PageDown: -10,
      PageUp: 10,
    };
    if (e.key === "Home") set(0);
    else if (e.key === "End") set(100);
    else if (e.key in map) set(pos + map[e.key]);
    else return;
    e.preventDefault();
  };

  const shown = clamp(pos + wiggle);
  const valueText = `${Math.round(shown)}% ${beforeLabel}, ${Math.round(100 - shown)}% ${afterLabel}`;

  return (
    <div
      ref={rootRef}
      className={`${styles.root} ${className}`.trim()}
      data-orientation={orientation}
      data-dragging={dragging ? "" : undefined}
      style={
        {
          "--mf-ic-pos": `${shown}%`,
          "--mf-ic-handle": handleColor,
          "--mf-ic-accent": accentColor,
          height,
          borderRadius,
          ...style,
        } as React.CSSProperties
      }
      onPointerDown={(e) => {
        if (e.button !== 0) return;
        e.currentTarget.setPointerCapture(e.pointerId);
        setDragging(true);
        fromPointer(e);
      }}
      onPointerMove={(e) => dragging && fromPointer(e)}
      onPointerUp={() => setDragging(false)}
      onPointerCancel={() => setDragging(false)}
    >
      <div className={styles.layer}>
        <Scene src={afterSrc} alt={afterLabel} vivid />
      </div>
      <div className={`${styles.layer} ${styles.before}`}>
        <Scene src={beforeSrc} alt={beforeLabel} vivid={false} />
      </div>
      {showLabels && (
        <>
          <span className={`${styles.tag} ${styles.tagBefore}`} data-hidden={shown < 14 ? "" : undefined} aria-hidden="true">
            {beforeLabel}
          </span>
          <span className={`${styles.tag} ${styles.tagAfter}`} data-hidden={shown > 86 ? "" : undefined} aria-hidden="true">
            {afterLabel}
          </span>
        </>
      )}
      <div className={styles.divider} aria-hidden="true" />
      <div
        role="slider"
        tabIndex={0}
        aria-label={`${beforeLabel} / ${afterLabel} comparison`}
        aria-orientation={orientation}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={Math.round(shown)}
        aria-valuetext={valueText}
        className={styles.handle}
        onKeyDown={onKeyDown}
      >
        <svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
          <path d="m9 7-5 5 5 5M15 7l5 5-5 5" />
        </svg>
      </div>
    </div>
  );
}

.root {
  --mf-ic-pos: 50%;
  --mf-ic-handle: #ffffff;
  --mf-ic-accent: #6366f1;
  position: relative;
  width: 100%;
  max-width: 44rem;
  overflow: hidden;
  border: 1px solid var(--mf-border, #2e2e38);
  background-color: var(--mf-surface, #141419);
  cursor: ew-resize;
  touch-action: pan-y;
  user-select: none;
  -webkit-user-select: none;
  isolation: isolate;
}

.root[data-orientation="vertical"] {
  cursor: ns-resize;
  touch-action: pan-x;
}

.layer {
  position: absolute;
  inset: 0;
}

.before {
  clip-path: inset(0 calc(100% - var(--mf-ic-pos)) 0 0);
}

.root[data-orientation="vertical"] .before {
  clip-path: inset(0 0 calc(100% - var(--mf-ic-pos)) 0);
}

.img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  pointer-events: none;
}

/* Default gradient scene */
.scene {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: linear-gradient(180deg, #1e1b4b 0%, #7c3aed 38%, #f472b6 62%, #fb923c 78%);
  filter: grayscale(0.92) contrast(0.82) brightness(0.78);
}

.scene[data-vivid] {
  filter: saturate(1.15);
}

.sun {
  position: absolute;
  left: 58%;
  top: 34%;
  width: 22%;
  aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 45%, #fff7ed 0%, #fde68a 40%, #fb923c 100%);
  box-shadow: 0 0 80px 30px rgb(251 146 60 / 0.45);
  transform: translate(-50%, -50%);
}

.ridge {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
}

.ridgeBack {
  height: 52%;
  background: linear-gradient(180deg, #6d28d9, #4c1d95);
  clip-path: polygon(0 48%, 12% 30%, 24% 44%, 38% 18%, 52% 40%, 66% 22%, 80% 42%, 92% 28%, 100% 36%, 100% 100%, 0 100%);
  opacity: 0.85;
}

.ridgeMid {
  height: 42%;
  background: linear-gradient(180deg, #4338ca, #1e1b4b);
  clip-path: polygon(0 38%, 16% 58%, 30% 30%, 46% 56%, 60% 34%, 76% 60%, 90% 40%, 100% 52%, 100% 100%, 0 100%);
}

.ridgeFront {
  height: 30%;
  background: linear-gradient(180deg, #1e1b4b, #0b0a1f);
  clip-path: polygon(0 30%, 20% 60%, 36% 40%, 54% 70%, 72% 44%, 88% 64%, 100% 46%, 100% 100%, 0 100%);
}

.water {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 14%;
  background: linear-gradient(180deg, rgb(251 146 60 / 0.35), rgb(15 12 41 / 0.95));
}

.tag {
  position: absolute;
  top: 0.875rem;
  z-index: 2;
  padding: 0.25rem 0.625rem;
  border-radius: 999px;
  background-color: rgb(9 9 11 / 0.55);
  backdrop-filter: blur(8px);
  color: #fafafa;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  pointer-events: none;
  transition: opacity 200ms ease;
}

.tagBefore {
  left: 0.875rem;
}

.tagAfter {
  right: 0.875rem;
}

.root[data-orientation="vertical"] .tagAfter {
  top: auto;
  bottom: 0.875rem;
}

.tag[data-hidden] {
  opacity: 0;
}

.divider {
  position: absolute;
  z-index: 3;
  top: 0;
  bottom: 0;
  left: var(--mf-ic-pos);
  width: 2px;
  background-color: var(--mf-ic-handle);
  box-shadow: 0 0 12px rgb(0 0 0 / 0.35);
  transform: translateX(-50%);
  pointer-events: none;
}

.root[data-orientation="vertical"] .divider {
  top: var(--mf-ic-pos);
  bottom: auto;
  left: 0;
  right: 0;
  width: auto;
  height: 2px;
  transform: translateY(-50%);
}

.handle {
  position: absolute;
  z-index: 4;
  top: 50%;
  left: var(--mf-ic-pos);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 999px;
  background-color: var(--mf-ic-handle);
  color: var(--mf-ic-accent);
  box-shadow: 0 4px 16px rgb(0 0 0 / 0.35), 0 0 0 4px rgb(255 255 255 / 0.18);
  transform: translate(-50%, -50%);
  outline: none;
  transition: scale 180ms cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 180ms ease;
}

.root[data-orientation="vertical"] .handle {
  top: var(--mf-ic-pos);
  left: 50%;
}

.root[data-orientation="vertical"] .handle svg {
  transform: rotate(90deg);
}

.root:hover .handle,
.root[data-dragging] .handle {
  scale: 1.08;
}

.handle:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: 3px;
  box-shadow: 0 4px 16px rgb(0 0 0 / 0.35), 0 0 0 6px color-mix(in srgb, var(--mf-ic-accent) 45%, transparent);
}

@media (prefers-reduced-motion: reduce) {
  .handle,
  .tag {
    transition: none;
  }

  .root:hover .handle,
  .root[data-dragging] .handle {
    scale: 1;
  }
}

