"use client";

import { useRef, useState } from "react";

const scene = "bg-[linear-gradient(180deg,#1e1b4b,#7c3aed_38%,#f472b6_62%,#fb923c_78%)]";

export function ImageCompareTailwind() {
  const [pos, setPos] = useState(50);
  const [drag, setDrag] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  const move = (x: number) => { const r = ref.current!.getBoundingClientRect(); setPos(Math.min(100, Math.max(0, ((x - r.left) / r.width) * 100))); };
  return (
    <div ref={ref} className="relative h-[360px] w-full max-w-2xl cursor-ew-resize touch-pan-y select-none overflow-hidden rounded-xl border border-zinc-800"
      onPointerDown={(e) => { e.currentTarget.setPointerCapture(e.pointerId); setDrag(true); move(e.clientX); }}
      onPointerMove={(e) => drag && move(e.clientX)} onPointerUp={() => setDrag(false)}>
      <div role="img" aria-label="After" className={`absolute inset-0 ${scene} saturate-150`} />
      <div role="img" aria-label="Before" className={`absolute inset-0 ${scene} brightness-75 grayscale`} style={{ clipPath: `inset(0 ${100 - pos}% 0 0)` }} />
      <div className="pointer-events-none absolute inset-y-0 w-0.5 -translate-x-1/2 bg-white" style={{ left: `${pos}%` }} />
      <div role="slider" tabIndex={0} aria-label="Before / After comparison" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(pos)}
        onKeyDown={(e) => { const d = e.key === "ArrowLeft" ? -2 : e.key === "ArrowRight" ? 2 : 0; if (d) { e.preventDefault(); setPos((p) => Math.min(100, Math.max(0, p + d))); } }}
        className="absolute top-1/2 grid size-11 -translate-x-1/2 -translate-y-1/2 place-items-center rounded-full bg-white text-indigo-500 shadow-lg outline-none focus-visible:ring-2 focus-visible:ring-zinc-200 focus-visible:ring-offset-2" style={{ left: `${pos}%` }}>
        &#8596;
      </div>
    </div>
  );
}
